 "content": "def transform(grid):
    """Fill the blank quadrants around the 3-cross with a distance pattern."""
    h, w = len(grid), len(grid[0])
    cross_r = next((r for r, row in enumerate(grid) if row.count(3) == w), None)
    cross_c = next((c for c in range(w) if all(grid[r][c] == 3 for r in range(h))), None)
    if cross_r is None or cross_c is None:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r == cross_r or c == cross_c:
                out[r][c] = 3
                continue
            vertical_distance = abs(r - cross_r)
            horizontal_distance = abs(c - cross_c)
            if horizontal_distance % 2 == 0 or (
                vertical_distance % 2 == 0 and horizontal_distance <= vertical_distance
            ):
                out[r][c] = 4
    return out
